import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { SqliteEventStore } from "@moe/store";
import { createStoreDependencies } from "./apps/daemon/src/daemon-store-dependencies.js";
import { createHealthProbeJob } from "./apps/daemon/src/monitoring/health-probe-ring.js";
import { HEALTH_PROBE_JOB_ID } from "./apps/daemon/src/monitoring/health-probe-contracts.js";
import { recordDeployReceipt } from "./apps/daemon/src/deployment/deploy-ledger.js";
const root=mkdtempSync(join(tmpdir(),"moe-health-interval-probe-"));
const path=join(root,"store.sqlite"), projectId="health-interval-probe";
let now=0, ordinal=0, calls=0, provider, store;
const handles=new Map();
const timer={set(tick,interval){const id=++ordinal; handles.set(id,{tick,interval,next:now+interval});return id;},
 clear(id){handles.delete(id);}};
async function advance(ms){
 const end=now+ms;
 while(handles.size){
  const due=Math.min(...[...handles.values()].map(x=>x.next)); if(due>end)break;
  now=due;
  for(const arm of [...handles.values()])if(arm.next===due){arm.next+=arm.interval;arm.tick();}
  await new Promise(resolve=>setTimeout(resolve,0));
 }
 now=end;
}
const http=async()=>{calls++;return 200;};
const config={storePath:path,projectId,credential:"local-probe-only",principalId:"operator-local",
 schedule:{timer},healthProbeHttp:http};
try{
 provider=createStoreDependencies(config);
 store=SqliteEventStore.openForProject(path,projectId);
 for(const environment of ["preview","staging"]){
  const receipt=recordDeployReceipt(store,{projectId,environment,sha:"a".repeat(40),
   imageDigest:"sha256:"+"b".repeat(64),refusal:null,releaseDecision:null,
   url:"http://127.0.0.1:1",decidedAt:"2026-09-06T00:00:00.000Z",decisionId:environment});
  assert.equal(receipt.ok,true);
 }
 assert.deepEqual([...handles.values()].map(x=>x.interval),[60000]);
 const custom=provider.schedules().register(HEALTH_PROBE_JOB_ID,
  createHealthProbeJob({store,projectId,http}),10000);
 assert.equal(custom.ok,true);
 await advance(60000);const before=calls;assert.equal(before,12);
 provider.close(); provider=undefined;assert.equal(handles.size,0);
 provider=createStoreDependencies(config);
 const restartIntervals=[...handles.values()].map(x=>x.interval);
 await advance(60000);
 console.log(JSON.stringify({environments:2,windowMs:60000,beforeCalls:before,
  afterCalls:calls-before,restartIntervals,durableIntervals:store.readEvents("durable-schedule/"+projectId)
   .map(e=>JSON.parse(new TextDecoder().decode(e.payload)).intervalMs)}));
}finally{
 provider?.close();store?.close();assert.equal(handles.size,0);
 rmSync(root,{recursive:true,force:true});
 console.log("HEALTH_INTERVAL_PROBE_CLEANUP_OK");
}
